import builtins

def _get_stream(dotenv_path):
    if dotenv_path:
        return builtins.open(dotenv_path, "r")
    return None

def load_dotenv(dotenv_path=None):
    stream = _get_stream(dotenv_path)
    if stream is None:
        return False
    stream.read()
    stream.close()
    return True
